import React from "react";

const friends = [
  { name: "Tod", status: "в сети", city: "Москва" },
  { name: "Olya", status: "была 5 мин назад", city: "СПб" },
  { name: "Vell", status: "в сети", city: "Казань" },
  { name: "Kolya", status: "слушает музыку", city: "Екб" },
  { name: "Loh", status: "офлайн", city: "Сочи" },
  { name: "Nina", status: "в сети", city: "Тбилиси" },
];

const FrendsContent = () => {
  return (
    <div className="page">
      <div className="pageHeader">
        <div>
          <div className="pageEyebrow">People</div>
          <h1 className="pageTitle">Друзья</h1>
          <p className="pageSubtitle">Список друзей и статусы — демо-данные</p>
        </div>
        <span className="badge">6 друзей</span>
      </div>

      <div className="grid3">
        {friends.map((f) => (
          <div key={f.name} className="card">
            <div className="feedItem" style={{ border: 0, padding: 0, gridTemplateColumns: "44px 1fr" }}>
              <div className="avatar" style={{ width: 44, height: 44, borderRadius: 12 }}>
                {f.name.slice(0, 1)}
              </div>
              <div>
                <div className="feedAuthor">{f.name}</div>
                <div className="feedTime">{f.status}</div>
                <div className="feedActions">
                  <span className="chip">{f.city}</span>
                  <span className="chip">Написать</span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default FrendsContent;
